Item.method_code:
return {
	constructor: function() {},

	RenderInnerContent: function(/* WrappedObject*/ renderObject) {
		const propertyName = renderObject.Attribute('propertyName') || 'id';
		const xmlNameRegExp = /^(?!XML)[a-z][\w0-9-]*$/i;
		const propertyValue = xmlNameRegExp.test(propertyName) ? renderObject.GetProperty(propertyName, '$null$') : '$null$';

		return '<span>' + dojox.html.entities.encode(propertyValue) + '</span>';
	},

	GetTreeName: function(/* WrappedObject*/ renderObject) {
		// eslint-disable-next-line prefer-rest-params
		let treeName = this.inherited(arguments);
		const keyedName  = renderObject.GetProperty('keyed_name', '$null$');
		const propertyName = renderObject.Attribute('propertyName') || 'id';

		treeName += ' - <i>' + dojox.html.entities.encode(keyedName) + '(' + propertyName + ')</i>' ;

		return treeName;
	}
};
